/* 布局·报摊头版 —— 刊头居中大标题，三栏新闻格 */
body.l-newspaper .hero {
  flex-direction: column; text-align: center; justify-content: center;
  border-bottom: 3px double var(--border); padding-bottom: 50px; gap: 30px;
}
body.l-newspaper .hero-right { display: none; }
body.l-newspaper .hero h1 { font-size: clamp(58px, 9vw, 104px); letter-spacing: -1px; }
body.l-newspaper .hero-left { display: flex; flex-direction: column; align-items: center; }
body.l-newspaper .hero-stats { justify-content: center; border-top: 1px solid var(--border); padding-top: 24px; margin-top: 14px; }
body.l-newspaper .hero::after {
  content: "STYLE GAZETTE · 风格公报 · 第 30 期"; margin-top: 18px;
  font-size: 12px; letter-spacing: 4px; color: var(--text-2);
}
body.l-newspaper .projects-grid { grid-template-columns: repeat(3, 1fr); }
body.l-newspaper .card.featured { grid-column: 1 / -1; }
body.l-newspaper .card.featured h3 { font-size: 26px; }
body.l-newspaper .card.featured .desc { font-size: 16px; max-width: 620px; }
body.l-newspaper .skills-wrap { grid-template-columns: 1fr 1fr; }
body.l-newspaper section > .reveal:first-child { text-align: center; }
body.l-newspaper .section-desc { margin-left: auto; margin-right: auto; }
@media (max-width: 720px) {
  body.l-newspaper .projects-grid { grid-template-columns: 1fr; }
}
